using NUnit.Framework;
using UnityEngine;
using ZFrame.Core;
using ZFrame.Data;
using ZFrame.View;

namespace ZFrame.Debug.Tests
{
    /// <summary>
    /// Real-prefab smoke (TASK-A-M3-01): the committed <c>ui_test_panel</c>
    /// prefab generated by <c>ZFrame.View.UISetup</c> is loaded through the REAL
    /// ResourceService (ResourcesProvider), pushed onto the real Popup canvas,
    /// driven end-to-end (button click fires the bus event, presenter updates
    /// the text, bus status event reaches the view) and popped cleanly. This is
    /// the deliberate UGUI coverage complement to the pure-fake stack fixtures.
    /// </summary>
    public sealed class UIPrefabSmokeTests
    {
        private UIRoot _root;
        private UIManager _ui;
        private ResourceService _resources;

        [SetUp]
        public void SetUp()
        {
            _root = UITestEnv.SetUp();
            _resources = new ResourceService(new ResourcesProvider());
            _ui = new UIManager(_resources, _root);
        }

        [TearDown]
        public void TearDown()
        {
            UITestEnv.TearDown();
            _resources.Clear();
        }

        [Test]
        public void SamplePrefab_IsCommitted_AndResolvesByKey()
        {
            GameObject prefab = Resources.Load<GameObject>("ui_test_panel");
            Assert.IsNotNull(prefab, "the Setup-generated prefab must live under Assets/UI/Resources with the exact key");
            Assert.IsNotNull(prefab.GetComponent<TestPanelView>());
        }

        [Test]
        public void PushPop_TestPanel_FullMvpLoopOverRealPrefabs()
        {
            Assert.IsTrue(_ui.Push<TestPanelView>(TestPanelView.DefaultConfig).GetAwaiter().GetResult());

            TestPanelView view;
            Assert.IsTrue(_ui.TryGetView(out view));
            Assert.AreSame(_root.GetLayerCanvas(UIConsts.UILayer.Popup).transform, view.transform.parent);
            Assert.AreEqual("UI_TestPanel ready", view.StatusText);
            Assert.AreEqual(1, _resources.GetRefCount("ui_test_panel"), "the prefab key must be reference-counted while open");

            // button fires the bus event → presenter updates the text
            view.TestButton.onClick.Invoke();
            Assert.AreEqual("clicked x1", view.StatusText);

            // bus status event → presenter → view (reverse direction)
            EventBus.Fire(new UiTestSetStatusEvent { Status = "external update" });
            Assert.AreEqual("external update", view.StatusText);

            Assert.IsTrue(_ui.Pop());
            Assert.IsTrue(view == null, "a cachePolicy None panel must be destroyed on pop (edit mode: immediately)");
            Assert.AreEqual(0, _resources.GetRefCount("ui_test_panel"), "pop must release the prefab reference");
        }

        [Test]
        public void Push_RejectsSecondTestPanelWhileOpen()
        {
            Assert.IsTrue(_ui.Push<TestPanelView>(TestPanelView.DefaultConfig).GetAwaiter().GetResult());
            Assert.IsFalse(_ui.Push<TestPanelView>(TestPanelView.DefaultConfig).GetAwaiter().GetResult());
            Assert.AreEqual(1, _ui.StackCount);
        }
    }
}
